    { id=20336, tab=2, tier=4, col=3, name="Weapon Mastery", icon="ability_warrior_weaponmastery", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Reduces the chance for your attacks to be dodged by 1% and reduces the duration of all Disarm effects used against you by 25%. This does not stack with other Disarm duration reducing effects.", "Reduces the chance for your attacks to be dodged by 2% and reduces the duration of all Disarm effects used against you by 50%. This does not stack with other Disarm duration reducing effects." }, localized={deDE={name="Waffenbeherrschung", tooltip={ "Verringert die Chance, dass Euren Angriffen ausgewichen wird, um 1% und die Dauer aller gegen Euch eingesetzten Entwaffnungseffekte um 25%. Nicht mit anderen Effekten stapelbar, welche die Dauer von Entwaffnung verringern.", "Verringert die Chance, dass Euren Angriffen ausgewichen wird, um 2% und die Dauer aller gegen Euch eingesetzten Entwaffnungseffekte um 50%. Nicht mit anderen Effekten stapelbar, welche die Dauer von Entwaffnung verringern." }}} },
