    { id=20340, tab=2, tier=6, col=1, name="Bloodthirst", icon="spell_nature_bloodlust", maxRank=1, prereqTalent=20335, prereqPoints=30, wired=true, tooltip={ "Instantly attack the target causing (Attack Power * 45 / 100) damage. In addition, the next 5 successful melee attacks will restore 10 health. This effect lasts 8 sec. Damage is based on your attack power." }, grant={ [1]=947512 }, localized={deDE={name="Blutdurst", tooltip={ "Greift das Ziel sofort an und verursacht (Angriffskraft * 45 / 100) Schaden. Zusätzlich stellen die nächsten 5 erfolgreichen Nahkampfangriffe 10 Gesundheit wieder her. Dieser Effekt hält 8 Sek. lang an. Der Schaden basiert auf Eurer Angriffskraft." }}} },
