    { id=20342, tab=2, tier=7, col=2, name="Improved Berserker Stance", icon="ability_racial_avatar", maxRank=5, prereqTalent=0, prereqPoints=35, wired=true, tooltip={ "Increases attack power by 2% and reduces threat caused by 2% while in Berserker Stance.", "Increases attack power by 4% and reduces threat caused by 4% while in Berserker Stance.", "Increases attack power by 6% and reduces threat caused by 6% while in Berserker Stance.", "Increases attack power by 8% and reduces threat caused by 8% while in Berserker Stance.", "Increases attack power by 10% and reduces threat caused by 10% while in Berserker Stance." }, localized={deDE={name="Verbesserte Berserkerhaltung", tooltip={ "Erhöht in Berserkerhaltung Eure Angriffskraft um 2% und verringert die verursachte Bedrohung um 2%.", "Erhöht in Berserkerhaltung Eure Angriffskraft um 4% und verringert die verursachte Bedrohung um 4%.", "Erhöht in Berserkerhaltung Eure Angriffskraft um 6% und verringert die verursachte Bedrohung um 6%.", "Erhöht in Berserkerhaltung Eure Angriffskraft um 8% und verringert die verursachte Bedrohung um 8%.", "Erhöht in Berserkerhaltung Eure Angriffskraft um 10% und verringert die verursachte Bedrohung um 10%." }}} },
    { id=20343, tab=2, tier=8, col=1, name="Rampage", icon="ability_warrior_rampage", maxRank=1, prereqTalent=20340, prereqPoints=40, wired=true, tooltip={ "Warrior goes on a rampage, increasing attack power by 30 and causing most successful melee attacks to increase attack power by an additional 30. This effect will stack up to 5 times. Lasts 30 sec. This ability can only be used after scoring a critical hit." }, grant={ [1]=947533 }, localized={deDE={name="Toben", tooltip={ "Der Krieger beginnt zu toben, wodurch seine Angriffskraft um 30 erhöht wird und die meisten erfolgreichen Nahkampfangriffe die Angriffskraft um weitere 30 erhöhen. Dieser Effekt ist bis zu 5-mal stapelbar. Hält 30 Sek. lang an. Diese Fähigkeit kann nur nach einem kritischen Treffer eingesetzt werden." }}} },
    { id=20344, tab=3, tier=0, col=0, name="Improved Bloodrage", icon="ability_racial_bloodrage", maxRank=2, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Increases the instant rage generated by your Bloodrage ability by 3.", "Increases the instant rage generated by your Bloodrage ability by 6." }, localized={deDE={name="Verbesserter Blutrausch", tooltip={ "Erhöht die sofort durch Eure Fähigkeit 'Blutrausch' erzeugte Wut um 3.", "Erhöht die sofort durch Eure Fähigkeit 'Blutrausch' erzeugte Wut um 6." }}} },
